import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

import {
  Line
} from "react-chartjs-2";

import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Legend
} from "chart.js";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Legend);

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  const mapRef = useRef();

  // 🧠 POINTS PER SECOND (FIXED)
  function computePointsPerSecond(data) {
    const bucket = {};

    data.forEach(p => {
      const ts = new Date(p.timestamp);

      // 🔥 KEY FIX: round to second
      const key = Math.floor(ts.getTime() / 1000);

      if (!bucket[key]) bucket[key] = 0;
      bucket[key]++;
    });

    const labels = Object.keys(bucket);
    const values = Object.values(bucket);

    return { labels, values };
  }

  // 🚀 FETCH DATA
  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path", {
        params: {
          start: startTime,
          end: endTime
        }
      });

      const d = res.data;

      if (!d.length) {
        alert("No data found");
        return;
      }

      setData(d);
      setIndex(0);

      const coords = d.map(p => ({
        lat: p.location.coordinates[1],
        lng: p.location.coordinates[0],
        alt: p.alt || 0,
        voltage: p.voltage || 0
      }));

      setPath(coords);

     if (coords.length && mapRef.current) {
  const first = coords[0];

  mapRef.current.setView(
    [first.lat, first.lng],
    19, // 🔥 full zoom
    { animate: true }
  );
}

    } catch (err) {
      console.error(err);
    }
  };

  // ▶ REAL-TIME PLAYBACK (BASED ON TIMESTAMP)
  useEffect(() => {
    if (!playing || data.length < 2) return;

    let i = index;

    function step() {
      if (i >= data.length - 1) return;

      const curr = new Date(data[i].timestamp);
      const next = new Date(data[i + 1].timestamp);

      // delay based on actual telemetry gap
      let delay = next - curr;

      // safety cap
      delay = Math.min(delay, 1000);

      setTimeout(() => {
        setIndex(prev => prev + 1);
        i++;
        step();
      }, delay);
    }

    step();

  }, [playing]);

  // 📍 FOLLOW DRONE
  useEffect(() => {
    if (path[index] && mapRef.current) {
      mapRef.current.flyTo(
        [path[index].lat, path[index].lng],
        18,
        { duration: 0.5 }
      );
    }
  }, [index]);

  // 📊 ALT + BATTERY
  const chartData = {
    labels: path.slice(0, index).map((_, i) => i),
    datasets: [
      {
        label: "Altitude (m)",
        data: path.slice(0, index).map(p => p.alt),
        borderColor: "cyan",
        tension: 0.3
      },
      {
        label: "Battery (V)",
        data: path.slice(0, index).map(p => p.voltage),
        borderColor: "yellow",
        tension: 0.3
      }
    ]
  };

  // 📊 POINTS PER SECOND (SYNCED)
  const pps = computePointsPerSecond(
    data.slice(0, index)
  );

  const ppsChart = {
    labels: pps.labels,
    datasets: [
      {
        label: "Points / Second",
        data: pps.values,
        borderColor: "lime",
        backgroundColor: "rgba(0,255,0,0.2)",
        tension: 0.3
      }
    ]
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        labels: { color: "white" }
      }
    },
    scales: {
      x: { ticks: { color: "white" } },
      y: { ticks: { color: "white" } }
    }
  };

  return (
    <div style={{ background: "black", color: "white", height: "100vh" }}>
      <h2>🚁 Drone Playback (Real-Time)</h2>

      {/* ⏱ TIME FILTER */}
      <div>
        Start:
        <input
          type="datetime-local"
          onChange={e => setStartTime(e.target.value)}
        />
        End:
        <input
          type="datetime-local"
          onChange={e => setEndTime(e.target.value)}
        />
        <button onClick={fetchData}>Apply</button>
      </div>

      {/* ▶ CONTROLS */}
      <div>
        <button onClick={() => setPlaying(true)}>▶ Play</button>
        <button onClick={() => setPlaying(false)}>⏸ Pause</button>
      </div>

      {/* 🗺 MAP */}
      <MapContainer
        center={[12.97, 77.59]}
        zoom={13}
        style={{ height: "60vh" }}
        whenCreated={map => (mapRef.current = map)}
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* PATH */}
        <Polyline
          positions={path.slice(0, index).map(p => [p.lat, p.lng])}
          color="cyan"
          weight={4}
        />

        {/* CURRENT POINT */}
        {path[index] && (
          <Marker
            position={[path[index].lat, path[index].lng]}
            icon={L.divIcon({
              html: `<div style="
                width:14px;height:14px;
                background:cyan;
                border-radius:50%;
                border:2px solid white;
                box-shadow:0 0 10px cyan;"></div>`
            })}
          >
            <Tooltip>
              Alt: {path[index].alt} m <br />
              Battery: {path[index].voltage} V
            </Tooltip>
          </Marker>
        )}
      </MapContainer>

      {/* 📊 ALT + BATTERY */}
      <div style={{ height: "20vh", background: "#111" }}>
        <Line data={chartData} options={chartOptions} />
      </div>

      {/* 📊 PPS */}
      <div style={{ height: "20vh", background: "#111" }}>
        <Line data={ppsChart} options={chartOptions} />
      </div>
    </div>
  );
}

export default App;
